static class RebirthWorldCharacterRepository{public static bool IsServerAuthority=true,Current=true,Throw,SaveKnown=true;public static RebirthTheorySoloState Saved;public static bool IsCurrentCachedRecord(RebirthWorldCharacterRecord r)=>Current&&ReferenceEquals(r,RebirthSkillAwardService.Record);public static bool SaveIfDirty(RebirthStablePlayerIdentity i,string s){if(Throw)throw new IOException();if(SaveKnown){Saved=RebirthSkillAwardService.Record.Progression.SoloTheory.Clone();RebirthSkillAwardService.Record.Dirty=false;}return SaveKnown;}public static bool HasSavedSoloTeachingOriginal(RebirthStablePlayerIdentity i,RebirthTheorySoloState s)=>Saved!=null&&Saved.TeachingOriginal.IsAcknowledged(RebirthTeachingOutcomeStore.Outcome.OriginalOrdinal)&&Saved.Evidence.Count==s.Evidence.Count;}
