class Test{static int count;static void Check(bool x,string why){if(!x)throw new Exception(count+" "+why);count++;}static void Main(){var p=new EntityPlayer();var w=new World{Player=p};p.world=w;GameManager.Instance.World=w;var r=new RebirthWorldCharacterRecord();RebirthSkillAwardService.Record=r;var i=new RebirthStablePlayerIdentity();var o=RebirthTeachingOutcomeStore.Outcome;RebirthTeachingOutcomeStore.Available=false;Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&r.Progression.SoloTheory==null,"unproved original cannot touch");RebirthTeachingOutcomeStore.Available=true;o.StudentApplied=false;Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&r.Progression.SoloTheory==null,"admission before actual student stage cannot touch");o.StudentApplied=true;w.Remote=true;Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&r.Progression.SoloTheory==null,"remote rejected");w.Remote=false;RebirthWorldCharacterRepository.SaveKnown=false;Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&r.Progression.SoloTheory.Evidence.Count==1,"unknown save retains exact evidence attempt");Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&r.Progression.SoloTheory.Evidence.Count==1,"unknown retry no duplicate");RebirthWorldCharacterRepository.Throw=true;Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&r.Progression.SoloTheory.Evidence.Count==1,"throw retains original attempt");RebirthWorldCharacterRepository.Throw=false;RebirthWorldCharacterRepository.SaveKnown=true;RebirthTeachingOutcomeStore.Ack=false;Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&RebirthWorldCharacterRepository.Saved.Evidence.Count==1,"journal ack hold after saved character");RebirthTeachingOutcomeStore.Ack=true;Check(RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&o.SoloEvidenceApplied&&r.Progression.SoloTheory.Evidence.Count==1,"exact retry completes once");Check(r.Progression.SoloTheory.Evidence[0].Difficulty==42&&r.Progression.SoloTheory.Evidence[0].Family=="social_transfer","saved continuous student target relevance");r.Progression.SoloTheory=RebirthWorldCharacterRepository.Saved.Clone();Check(RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&r.Progression.SoloTheory.Evidence.Count==1,"reload original retirement no duplicate");r.Progression.SoloTheory.Evidence.Clear();Check(RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r)&&r.Progression.SoloTheory.Evidence.Count==0,"retired outcome cannot refill pruned evidence");RebirthWorldCharacterRepository.Current=false;Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r),"stale record refuses");RebirthWorldCharacterRepository.Current=true;var replaced=new World{Player=p};GameManager.Instance.World=replaced;Check(!RebirthTheorySoloTeachingCompletion.TryApply(o,p,i,r),"replaced native world refuses");Console.WriteLine(count+" PASS actual durable Teaching Solo completion producer");}}